$root='api/LuxuryApp.Application/Modules/MantenimientoLuxuryApp/PiscinasBitacora'; $dto="$root/DTOs"; $src=Get-Content "$dto/PiscinaBitacoraAddOrEditDTO.cs" -Raw; Set-Content "$dto/CreatePoolLogDTO.cs" ($src.Replace('PiscinaBitacoraAddOrEditDTO','CreatePoolLogDTO')) -NoNewline; Set-Content "$dto/UpdatePoolLogDTO.cs" ($src.Replace('PiscinaBitacoraAddOrEditDTO','UpdatePoolLogDTO')) -NoNewline; $names=@{'PiscinaBitacoraDTO'='PoolLogDTO';'PiscinaBitacoraExcelDTO'='PoolLogExcelDTO';'PiscinaBitacoraExcelRowDTO'='PoolLogExcelRowDTO';'PiscinaBitacoraImportRequest'='PoolLogImportRequestDTO';'PiscinaBitacoraImportResultDTO'='PoolLogImportResultDTO'}; foreach($k in $names.Keys){$old=Get-Content "$dto/$k.cs" -Raw; Set-Content "$dto/$($names[$k]).cs" ($old.Replace($k,$names[$k])) -NoNewline}; Remove-Item "$dto/PiscinaBitacoraAddOrEditDTO.cs","$dto/PiscinaBitacoraDTO.cs","$dto/PiscinaBitacoraExcelDTO.cs","$dto/PiscinaBitacoraExcelRowDTO.cs","$dto/PiscinaBitacoraImportRequest.cs","$dto/PiscinaBitacoraImportResultDTO.cs"; $map=@{'PiscinaBitacoraAddOrEditDTO'='CreatePoolLogDTO';'PiscinaBitacoraDTO'='PoolLogDTO';'PiscinaBitacoraExcelDTO'='PoolLogExcelDTO';'PiscinaBitacoraExcelRowDTO'='PoolLogExcelRowDTO';'PiscinaBitacoraImportRequest'='PoolLogImportRequestDTO';'PiscinaBitacoraImportResultDTO'='PoolLogImportResultDTO'}; Get-ChildItem $root -Recurse -File -Filter *.cs | ForEach-Object{$c=Get-Content $_.FullName -Raw; foreach($k in $map.Keys){$c=$c.Replace($k,$map[$k])}; $c=$c.Replace('UpdateAsync(Guid id, CreatePoolLogDTO','UpdateAsync(Guid id, UpdatePoolLogDTO').Replace('MapPut("{id:guid}", async (Guid id, CreatePoolLogDTO','MapPut("{id:guid}", async (Guid id, UpdatePoolLogDTO'); Set-Content $_.FullName $c -NoNewline};
